461	    /// The production tag provider behind the real executor, with an effect counter in place of the real publish.
462	    struct TagOnlyProviders<'a> {
463	        intent: ReleaseIntentV1,
464	        operation: crate::commands::release::provider::PreparedOperation,
465	        root: &'a std::path::Path,
466	        runner: &'a dyn callisto_model::CommandRunner,
467	        effects: std::cell::Cell<usize>,
468	    }
469	
470	    impl TagOnlyProviders<'_> {
471	        fn request<'r>(
472	            &'r self,
473	            id: &'r ReleaseOperationId,
474	        ) -> crate::commands::release::provider::ProviderRequest<'r> {
475	            crate::commands::release::provider::ProviderRequest {
476	                id,
477	                operation: &self.operation,
478	                artifacts: None,
479	            }
480	        }
481	    }
482	
483	    impl ReleaseProviderSet for TagOnlyProviders<'_> {
484	        fn intent(&self) -> &ReleaseIntentV1 {
485	            &self.intent
486	        }
487	
488	        fn recheck_trust(&self) -> Result<(), GraphError> {
489	            Ok(())
490	        }
491	
492	        fn preflight(
493	            &self,
494	            id: &ReleaseOperationId,
495	            _artifacts: Option<&VerifiedArtifactManifest<'_>>,
496	        ) -> Result<ReleasePreflight, GraphError> {
497	            use crate::commands::release::provider::{tag::TagProvider, ProviderContext, ReleaseProvider};
498	            let remote = crate::commands::release::optional_git_remote(self.root, self.runner)?;
499	            TagProvider.preflight(
500	                &ProviderContext::new(self.root, self.runner, remote.as_ref()),
501	                &self.request(id),
502	            )
503	        }
504	
505	        fn observe(
506	            &self,
507	            _id: &ReleaseOperationId,
508	            _artifacts: Option<&VerifiedArtifactManifest<'_>>,
509	        ) -> Result<callisto_model::ProviderObservationV1, GraphError> {
510	            unreachable!("the executor preflights before it observes")
511	        }
512	
513	        fn publish(
514	            &self,
515	            _permit: &ApplyPermit,
516	            _proof: &callisto_model::AbsentProof,
517	            _id: &ReleaseOperationId,
518	            _artifacts: Option<&VerifiedArtifactManifest<'_>>,
519	        ) -> Result<callisto_model::ExactEvidence, GraphError> {
520	            self.effects.set(self.effects.get() + 1);
521	            Err(GraphError::ReleaseInvariant {
522	                detail: "the effect must not run".to_owned(),
523	            })
524	        }
525	    }
