527	    /// A git whose `rev-parse` fails fatally and whose remote reads as empty; it remembers each subcommand it ran.
528	    struct BrokenLocalGit(std::sync::Mutex<Vec<String>>);
529	
530	    impl callisto_model::CommandRunner for BrokenLocalGit {
531	        fn run(
532	            &self,
533	            _program: &str,
534	            args: &[&str],
535	            _cwd: &std::path::Path,
536	        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
537	            let subcommand = args.first().copied().unwrap_or_default();
538	            self.0.lock().unwrap().push(subcommand.to_owned());
539	            let (exit_code, stdout, stderr) = match subcommand {
540	                "remote" => (0, "https://github.com/orin-dx/callisto", ""),
541	                "rev-parse" => (128, "", "fatal: not a git repository\n"),
542	                _ => (0, "", ""),
543	            };
544	            Ok(callisto_model::CommandOutput {
545	                exit_code: Some(exit_code),
546	                stdout: stdout.to_owned(),
547	                stderr: stderr.to_owned(),
548	            })
549	        }
550	    }
