1	//! Wall-clock and retry policy shared by every release provider.
2	
3	use std::path::Path;
4	use std::time::Duration;
5	
6	use callisto_model::{CommandError, CommandOutput, CommandRunner, ProviderObservationV1, Version};
7	
8	use crate::GraphError;
9	
10	/// Wall-clock deadlines for every command the release path issues. Without
11	/// them one hung provider consumes the whole CI job budget; a breach surfaces
12	/// as `CommandError::TimedOut` (E025) and, after `Attempting` is persisted,
13	/// fails closed exactly as any other dispatch error.
14	pub(crate) mod timeouts {
15	    use std::time::Duration;
16	
17	    /// `cargo publish`, `npm publish`, `python -m build`, `twine upload`.
18	    pub(crate) const PUBLISH: Duration = Duration::from_secs(900);
19	    /// The subprocess deadline around one registry query (`cargo info`, `npm view`, `curl` PyPI simple index).
20	    pub(crate) const REGISTRY_QUERY: Duration = Duration::from_secs(300);
21	    /// `gh attestation verify`.
22	    pub(crate) const ATTESTATION_VERIFY: Duration = Duration::from_secs(120);
23	    /// `gh api`.
24	    pub(crate) const FORGE_API: Duration = Duration::from_secs(60);
25	    /// `git ls-remote`.
26	    pub(crate) const GIT_LS_REMOTE: Duration = Duration::from_secs(60);
27	    /// `git push`.
28	    pub(crate) const GIT_PUSH: Duration = Duration::from_secs(120);
29	    /// `gh release create`.
30	    pub(crate) const FORGE_RELEASE_CREATE: Duration = Duration::from_secs(120);
31	    /// `gh release upload`.
32	    pub(crate) const FORGE_ASSET_UPLOAD: Duration = Duration::from_secs(600);
33	    /// Purely local git reads (`rev-parse`, `for-each-ref`, `remote get-url`).
34	    pub(crate) const LOCAL_GIT: Duration = Duration::from_secs(60);
35	}
36	
37	/// External programs and the remote name the release path invokes.
38	pub(crate) mod programs {
39	    pub(crate) const GIT: &str = "git";
40	    pub(crate) const GH: &str = "gh";
41	    pub(crate) const CARGO: &str = "cargo";
42	    pub(crate) const NPM: &str = "npm";
43	    /// The PyPI simple-index observation query (`curl -sS -i`).
44	    pub(crate) const CURL: &str = "curl";
45	    /// The remote whose push URL is the trusted release destination.
46	    pub(crate) const GIT_REMOTE: &str = "origin";
47	}
48	
49	/// Total tries for one read-only observation, including the first.
50	pub(crate) const OBSERVATION_MAX_ATTEMPTS: u32 = 5;
51	
52	/// Longest single wait, and the clamp applied to a server's `Retry-After`.
53	pub(crate) const OBSERVATION_BACKOFF_CAP: Duration = Duration::from_secs(300);
54	
55	/// Exponential backoff between observation attempts: 2s, 4s, 8s, 16s.
56	pub(crate) fn observation_backoff(attempt: u32) -> Duration {
57	    Duration::from_secs(2u64.saturating_pow(attempt + 1)).min(OBSERVATION_BACKOFF_CAP)
58	}
59	
60	/// How long a version this run just published may take to appear on its registry's read path.
61	///
62	/// Sized to the cache lifetime of the read the observation uses, plus a minute of slack: npm serves a package's
63	/// document with `max-age=300` (a missing package's 404 too), so a read that primed the cache just before the publish
64	/// can answer stale for up to five minutes. `cargo publish` waits for the index itself.
65	pub(crate) fn default_visibility_window(ecosystem: callisto_model::Ecosystem) -> Duration {
66	    match ecosystem {
67	        callisto_model::Ecosystem::Npm | callisto_model::Ecosystem::Pypi => Duration::from_secs(360),
68	        _ => Duration::from_secs(120),
69	    }
70	}
71	
72	/// The waits between looks at a version that is not yet visible: 15s, 45s, 2m, then 3m steps.
73	///
74	/// A look is the first thing done after the publishes are issued, so a registry that purges its cache shows the
75	/// version at once, and the earlier packages of a release have aged by the time the last is looked at. What is left
76	/// is a stale cache that expires on its own, up to five minutes after it was filled, so the looks are spaced to catch
77	/// that, not to poll: five looks cover the default six-minute window.
78	pub(crate) fn visibility_backoff(attempt: u32) -> Duration {
79	    const STEPS: [u64; 3] = [15, 45, 120];
80	    const LAST_STEP: u64 = 180;
81	    Duration::from_secs(
82	        usize::try_from(attempt)
83	            .ok()
84	            .and_then(|index| STEPS.get(index))
85	            .copied()
86	            .unwrap_or(LAST_STEP),
87	    )
88	}
89	
90	/// Retries `attempt` while it reports `Transient`, until `window` of waiting is spent; the last answer is then reported.
91	///
92	/// Unlike [`retry_observation`] the bound is time, not tries: how long a registry lags is a property of the registry,
93	/// not of how many times it was asked.
94	pub(crate) fn retry_within_window<T>(
95	    sleeper: &dyn Sleeper,
96	    window: Duration,
97	    mut attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
98	) -> Result<T, GraphError> {
99	    let mut waited = Duration::ZERO;
100	    let mut index = 0;
101	    loop {
102	        match attempt()? {
103	            Attempt::Settled(value) => return Ok(value),
104	            Attempt::Transient { value, retry_after } => {
105	                let remaining = window.saturating_sub(waited);
106	                if remaining.is_zero() {
107	                    return Ok(value);
108	                }
109	                let wait = retry_after
110	                    .unwrap_or_else(|| visibility_backoff(index))
111	                    .clamp(Duration::from_secs(1), OBSERVATION_BACKOFF_CAP)
112	                    .min(remaining);
113	                sleeper.sleep(wait);
114	                waited += wait;
115	                index += 1;
116	            }
117	        }
118	    }
119	}
120	
121	/// Re-observes this run's own publish while the registry reads `Absent` or cannot be asked, for up to `window`; any
122	/// other answer is final. Each `observe` is one look: its own retries would wait outside the window.
123	pub(crate) fn observe_within_window(
124	    sleeper: &dyn Sleeper,
125	    window: Duration,
126	    mut observe: impl FnMut() -> Result<Attempt<ProviderObservationV1>, GraphError>,
127	) -> Result<ProviderObservationV1, GraphError> {
128	    retry_within_window(sleeper, window, || {
129	        Ok(match observe()? {
130	            Attempt::Settled(
131	                observation @ (ProviderObservationV1::Absent | ProviderObservationV1::Indeterminate { .. }),
132	            ) => Attempt::Transient {
133	                value: observation,
134	                retry_after: None,
135	            },
136	            attempt => attempt,
137	        })
138	    })
139	}
140	
141	/// GitHub's reads lag its writes by seconds; waits of 2s to 32s cover about a minute.
142	pub(crate) const EFFECT_VISIBILITY_ATTEMPTS: u32 = 6;
143	
144	/// Re-observes this run's own effect while it reads `Absent`; any other answer is final.
145	pub(crate) fn observe_until_visible(
146	    sleeper: &dyn Sleeper,
147	    mut observe: impl FnMut() -> Result<ProviderObservationV1, GraphError>,
148	) -> Result<ProviderObservationV1, GraphError> {
149	    let mut index = 0;
150	    loop {
151	        let observation = observe()?;
152	        if !matches!(observation, ProviderObservationV1::Absent) || index + 1 >= EFFECT_VISIBILITY_ATTEMPTS {
153	            return Ok(observation);
154	        }
155	        sleeper.sleep(observation_backoff(index));
156	        index += 1;
157	    }
158	}
159	
160	/// One attempt's result: either it settled the question, or it left the answer
161	/// unknown for a reason that may resolve on its own.
162	#[derive(Debug, PartialEq, Eq)]
163	pub(crate) enum Attempt<T> {
164	    Settled(T),
165	    /// `value` is the answer to report if every attempt is exhausted.
166	    Transient {
167	        value: T,
168	        retry_after: Option<Duration>,
169	    },
170	}
171	
172	/// The wall-clock wait, injected so tests exercise the schedule without it.
173	pub(crate) trait Sleeper: Sync {
174	    fn sleep(&self, duration: Duration);
175	}
176	
177	pub(crate) struct ThreadSleeper;
178	
179	impl Sleeper for ThreadSleeper {
180	    fn sleep(&self, duration: Duration) {
181	        std::thread::sleep(scaled_for_tests(duration));
182	    }
183	}
184	
185	/// Test-only, like cargo's `__CARGO_TEST_*`: e2e tests can't inject a `Sleeper`.
186	fn scaled_for_tests(duration: Duration) -> Duration {
187	    match std::env::var("__CALLISTO_TEST_SLEEP_SCALE") {
188	        Ok(raw) => match raw.parse::<f64>() {
189	            Ok(scale) if scale.is_finite() && scale >= 0.0 => duration.mul_f64(scale),
190	            _ => duration,
191	        },
192	        Err(_) => duration,
193	    }
194	}
195	
196	/// A command that could not be run at all (timed out or failed to spawn), unlike one that ran and exited non-zero.
197	#[derive(Debug)]
198	pub(crate) struct CommandUnavailable;
199	
200	/// Translates a timeout or I/O failure into `CommandUnavailable` so `retry_observation` can retry it, instead
201	/// of propagating a hard `GraphError`. `NotFound` stays a hard error: retrying can't install a missing program.
202	pub(crate) fn run_observation(
203	    runner: &dyn CommandRunner,
204	    program: &str,
205	    args: &[&str],
206	    cwd: &Path,
207	    timeout: Duration,
208	    quiet: bool,
209	) -> Result<Result<CommandOutput, CommandUnavailable>, GraphError> {
