333	    let root = canonical_root(root)?;
334	    let workspace = Workspace::load(root.clone(), locator, runner)?;
335	    let trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
336	    let source = source_from_trust(&trust);
337	    let artifact_policy = artifact_policy_from_intent(&received)?;
338	    // This is an integrity re-derivation, not a fresh plan: any diagnostic it would
