375	/// The longest an advisory observation waits between its own tries: one retry past a transient failure, no more.
376	const ADVISORY_OBSERVATION_PATIENCE: std::time::Duration = std::time::Duration::from_secs(1);
377	
378	/// The most registry or remote observations in flight at once.
379	const OBSERVATION_WORKERS: usize = 8;
380	
381	/// `work` over every item, results in item order. Observations are independent reads that spend their time waiting on a
382	/// registry or remote, so they run side by side instead of one after another.
383	pub(super) fn in_parallel<I: Sync, T: Send>(items: &[I], work: impl Fn(&I) -> T + Sync) -> Vec<T> {
384	    let workers = items.len().min(OBSERVATION_WORKERS);
385	    if workers <= 1 {
386	        return items.iter().map(work).collect();
387	    }
388	    let next = std::sync::atomic::AtomicUsize::new(0);
389	    let done = std::sync::Mutex::new(Vec::with_capacity(items.len()));
390	    std::thread::scope(|scope| {
391	        for _ in 0..workers {
392	            scope.spawn(|| loop {
393	                let index = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
394	                let Some(item) = items.get(index) else {
395	                    break;
396	                };
397	                let value = work(item);
398	                done.lock()
399	                    .unwrap_or_else(std::sync::PoisonError::into_inner)
400	                    .push((index, value));
401	            });
